// src/infrastructure/rl/networkDrivePolicyFixture.spec.ts
//
// The **transfer check** for the cooperative-driving policy.
//
// The weights the MAPPO trainer produces must be interpretable by the
// browser: the same weights and the same observation must give the same
// action in Python and in the browser. The policy is **parameter-shared**
// - one actor serves every driver - so the browser runs it per car.
//
// The fixture is generated by the backend (it owns the training side):
//   cd TraffSim3D-backend
//   .\.venv\Scripts\python.exe scripts\gen_drive_policy_fixture.py \
//       --weights <network_drive_weights.json>
// It holds the exported weights of the policy trained by
// `app.apps.rl.drive_mappo`, the observations **the policy actually met
// while driving**, and the action each observation must produce.
//
// The observations are fixed vectors, so this check is about the forward
// pass alone. The browser's *live* observation builder is a different
// question - and the one the repository already knows the hard way: a
// normalisation that is wrong on one side only does not turn any test
// red (the contract compares the schema, not the numbers).

import { describe, it, expect } from 'vitest'
import fixture from './fixtures/network-drive-policy-fixture.json'
import { mlpForwardMean } from './mlpInference'
import type { PolicyWeights } from './types'

const POLICY: PolicyWeights = {
  name: fixture.name,
  obs_dim: fixture.obs_dim,
  action_dim: fixture.action_dim,
  action_space: fixture.action_space as PolicyWeights['action_space'],
  hidden_sizes: fixture.hidden_sizes,
  layers: fixture.layers as PolicyWeights['layers'],
}

const OBSERVATIONS = fixture.observations as number[][]
const EXPECTED = fixture.expected_actions as number[][]

describe('the cooperative driving policy transfer check', () => {
  it('is a continuous two-action policy over the 23-dim observation', () => {
    expect(POLICY.action_space).toBe('continuous')
    expect(POLICY.action_dim).toBe(2)
    expect(POLICY.obs_dim).toBe(23)
    // A continuous policy carries the Gaussian's log-std.
    expect(POLICY.layers.log_std).toBeDefined()
  })

  it('has the layer layout the browser hard-codes', () => {
    expect(POLICY.hidden_sizes).toEqual([64, 64])
    expect(POLICY.layers['policy_net.0.weight']).toHaveLength(64)
    expect(POLICY.layers['policy_net.0.weight'][0]).toHaveLength(23)
    expect(POLICY.layers['policy_net.2.weight']).toHaveLength(64)
    expect(POLICY.layers['policy_net.2.weight'][0]).toHaveLength(64)
    expect(POLICY.layers['action_net.weight']).toHaveLength(2)
    expect(POLICY.layers['action_net.weight'][0]).toHaveLength(64)
  })

  it('the browser reproduces the Python action for every committed observation', () => {
    expect(OBSERVATIONS.length).toBeGreaterThan(0)
    expect(OBSERVATIONS).toHaveLength(EXPECTED.length)

    OBSERVATIONS.forEach((observation, index) => {
      expect(observation).toHaveLength(23)
      const action = mlpForwardMean(observation, POLICY)
      const expected = EXPECTED[index]!
      // The browser computes in float64 and the fixture was pinned in
      // float64 (the pure-Python reference), so the two agree to the
      // last bits the double carries - the tolerance is the float32
      // detour the trainer's own actor takes, not a slack.
      expect(action[0]).toBeCloseTo(expected[0], 6)
      expect(action[1]).toBeCloseTo(expected[1], 6)
    })
  })

  it('the policy actually discriminates — the fixture is not one action', () => {
    // A fixture whose observations all produced the same action would
    // be satisfied by a forward pass that always returns that action.
    const distinct = new Set(EXPECTED.map((action) => action.map((v) => v.toFixed(3)).join(',')))
    expect(distinct.size).toBeGreaterThan(1)
  })

  it('the observations are the ones the policy met (they are not all zero)', () => {
    const nonZero = OBSERVATIONS.filter((observation) => observation.some((v) => v !== 0))
    expect(nonZero.length).toBe(OBSERVATIONS.length)
  })
})
